def validate_pnf(grammar: Grammar) -> List[str]:
    """Return a list of human readable PNF violations (empty when in PNF).

    Checked properties: no inline sub-rules, quantified rules quantify exactly
    one symbol, no direct left/right recursion, no indirect left recursion, no
    unproductive (pass-through) cycles and no unreachable rules.
    """
    problems: List[str] = []
    normalizer = PNFNormalizer()

    for name, rule in grammar.rules.items():
        for sym in rule.symbols:
            if isinstance(sym, GrammarRule):
                problems.append(f"rule {name!r} contains inline sub-rule "
                                f"{sym.name!r}")
        if rule.rule_type in QUANTIFIED_TYPES and len(rule.symbols) != 1:
            problems.append(f"quantified rule {name!r} has "
                            f"{len(rule.symbols)} symbols (expected 1)")

    for name in normalizer.find_direct_recursion(grammar):
        problems.append(f"rule {name!r} is directly recursive")

    left_cycle = normalizer._find_cycle(grammar, normalizer._left_corner_symbols)
    if left_cycle:
        problems.append("left recursion cycle: " + " -> ".join(left_cycle))

    flat_cycle = normalizer._find_cycle(grammar, normalizer._pass_through_symbols)
    if flat_cycle:
        problems.append("unproductive cycle: " + " -> ".join(flat_cycle))

    reachable = normalizer.reachable_rules(grammar)
    for name in grammar.rules:
        if name not in reachable:
            problems.append(f"rule {name!r} is unreachable")

    return problems

